rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("CÓLICO NEFRÍTICO",120,nowrap=True)+big(f'CON FIEBRE <span style="color:{R}">YA NO ES</span> UN CÓLICO SIMPLE',116)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Analgesia por escalones, qué imagen pedir y cuándo llamar a Urología. Con ficha final.</div>',cover=True),
page(2,N,T,kicker("PASO 1 · ANALGESIA")+big("AINE PRIMERO",170,R,True)+rows(row("Vía","IV o IM"),row("Ejemplo","Dexketoprofeno o diclofenaco"),row("Si no cede","Repite a los 30–60 min"))+note("Los antiinflamatorios controlan el dolor mejor que los opioides y con menos vómitos. Valora el riesgo cardiovascular y la función renal antes de darlos.")),
page(3,N,T,kicker("PASO 2 · SI NO BASTA")+big("SEGUNDO ESCALÓN",122,nowrap=True)+rows(line("Metamizol IV, asociado al antiinflamatorio"),line("Opioide (tramadol) si el dolor persiste",True),line("Antiemético si hay vómitos (metoclopramida)"))+note("No fuerces la hidratación en la fase aguda: aumenta el dolor y no acelera la expulsión.")),
page(4,N,T,kicker("PASO 3 · IMAGEN")+big("¿A QUIÉN Y QUÉ?",132,nowrap=True)+rows(row("Primera prueba","Ecografía (vale a pie de cama)"),row("¿Fiebre?","Ecografía: ¿hay dilatación?"),row("TC sin contraste","Solo si va mal o hay dudas"))+note("TC si mal estado general, fracaso renal, dolor refractario o duda diagnóstica. El cólico típico que responde no necesita imagen urgente.")),
page(5,N,T,kicker("LA URGENCIA REAL")+big("OBSTRUIDO E INFECTADO",104,R)+'<div style="font-size:50px;font-weight:800;line-height:1.2">Riñón obstruido + infección = descompresión urgente</div>'+rows(line("Cultivos, antibiótico y aviso a Urología"),line("Catéter doble J o nefrostomía; la litiasis se trata después",True))),
page(6,N,T,kicker("ALTA O INGRESO")+big("AVISA A UROLOGÍA SI…",104)+rows(line("Sepsis, o fiebre con riñón dilatado",True),line("Fracaso renal, anuria o riñón único"),line("Dolor que no cede con la analgesia"))+note("La fiebre aislada sin dilatación ni sepsis se trata como infección; no es por sí sola motivo de aviso. Al alta: AINE pautado y, en litiasis distal de 5–10 mm, tamsulosina (fuera de ficha técnica).")),
page(7,N,T,ficha_body("CÓLICO NEFRÍTICO","Adulto",[("1. ANALGESIA","AINE IV o IM (dexketoprofeno o diclofenaco), repetible a los 30–60 min",True),("2. SI NO CEDE","Añade metamizol IV. Opioide (tramadol) de segunda línea"),("IMAGEN","Ecografía si fiebre o duda. TC solo si mal estado, fracaso renal, dolor refractario o duda diagnóstica"),("UROLOGÍA YA","Sepsis o fiebre con riñón dilatado, fracaso renal, anuria, riñón único, dolor refractario",True),("AL ALTA","AINE pautado. Tamsulosina si litiasis distal de 5–10 mm"),("EVITA","Sobrehidratar en la fase aguda")],"EAU Guidelines on Urolithiasis 2026; García Sierra A, et al. Cólico nefrítico en Atención Primaria",size=100,fs=32),ficha="06"),
]
